from itertools import combinations

# D4 elements as strings
elements = ['e', 'r', 'r2', 'r3', 's', 'sr', 'sr2', 'sr3']

# Multiplication table from the problem
# row * col
table = {
    'e':    {'e':'e',  'r':'r',  'r2':'r2','r3':'r3','s':'s',  'sr':'sr','sr2':'sr2','sr3':'sr3'},
    'r':    {'e':'r',  'r':'r2', 'r2':'r3','r3':'e', 's':'sr', 'sr':'sr2','sr2':'sr3','sr3':'s'},
    'r2':   {'e':'r2', 'r':'r3', 'r2':'e', 'r3':'r', 's':'sr2','sr':'sr3','sr2':'s',  'sr3':'sr'},
    'r3':   {'e':'r3', 'r':'e',  'r2':'r', 'r3':'r2','s':'sr3','sr':'s',  'sr2':'sr', 'sr3':'sr2'},
    's':    {'e':'s',  'r':'sr3','r2':'sr2','r3':'sr','s':'e',  'sr':'r3','sr2':'r2','sr3':'r'},
    'sr':   {'e':'sr', 'r':'s',  'r2':'sr3','r3':'sr2','s':'r','sr':'e',  'sr2':'r3','sr3':'r2'},
    'sr2':  {'e':'sr2','r':'sr', 'r2':'s', 'r3':'sr3','s':'r2','sr':'r', 'sr2':'e',  'sr3':'r3'},
    'sr3':  {'e':'sr3','r':'sr2','r2':'sr', 'r3':'s',  's':'r3','sr':'r2','sr2':'r', 'sr3':'e'},
}

def mul(a, b):
    return table[a][b]

def inv(a):
    for b in elements:
        if mul(a,b)=='e' and mul(b,a)=='e':
            return b
    return None

def is_subgroup(subset):
    s = set(subset)
    if 'e' not in s:
        return False
    for a in subset:
        if inv(a) not in s:
            return False
        for b in subset:
            if mul(a,b) not in s:
                return False
    return True

# Find all subgroups
subgroups = []
for size in range(1, len(elements)+1):
    for combo in combinations(elements, size):
        if 'e' in combo and is_subgroup(combo):
            subgroups.append(frozenset(combo))

# Deduplicate
unique = set(subgroups)
print(f"Total subgroups: {len(unique)}")
print()

# Sort by size
sorted_subs = sorted(unique, key=lambda s: (len(s), sorted(s)))
for sg in sorted_subs:
    elems = sorted(sg)
    print(f"  Order {len(sg)}: {{{', '.join(elems)}}}")

# Verify element orders
print("\nElement orders:")
for a in elements:
    power = a
    for i in range(2, 9):
        power = mul(power, a)
        if power == 'e':
            print(f"  {a}: order {i}")
            break
